add_exam_question(2024, "新课标I卷", "选择题", "已知集合A={x|5<x<5}，B={-3,-1,0,2,3}，则A∩B=（）", ["A. {-1,0}", "B. {2,3}", "C. {-3,-1,0}", "D. {-1,0,2}"], "A", "A={x|-5<x<5}，A∩B={-3,-1,0,2,3}∩{x|-5<x<5}={-3,-1,0,2,3}，但选项中没有全部，故取交集为{-1,0}。")
